#include "RSUApp.h"
#include "CavMsg_m.h"
#include <chrono>
#include <cmath>
#include <cstdlib>
using namespace omnetpp; using cavpqc::Bytes; using cavpqc::PqcCrypto;
Define_Module(RSUApp);
namespace { template <typename F> auto timed(cSimpleModule* m,simsignal_t s,F&& f){auto start=std::chrono::steady_clock::now();auto r=f();m->emit(s,std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());return r;} int bytes(const CavMsg& m){return 48+std::string(m.getSessionId()).size()+std::string(m.getSenderId()).size()+std::string(m.getReceiverId()).size()+(std::string(m.getKemPublicKeyHex()).size()+std::string(m.getKemCiphertextHex()).size()+std::string(m.getSigningPublicKeyHex()).size()+std::string(m.getSignatureHex()).size()+std::string(m.getNonceHex()).size()+std::string(m.getTranscriptHashHex()).size()+std::string(m.getFinishedTagHex()).size())/2;} }
void RSUApp::initialize(){cryptoTimeSignal_=registerSignal("cryptoProcessingMs");handshakeLatencySignal_=registerSignal("handshakeLatency");successSignal_=registerSignal("v2rSuccess");failureSignal_=registerSignal("v2rFailure");overheadSignal_=registerSignal("messageOverheadBytes");try{signing_=timed(this,cryptoTimeSignal_,[&]{return crypto_.signatureKeygen();});}catch(const std::exception& e){fail(e.what());}}
std::int64_t RSUApp::nowMs()const{return static_cast<std::int64_t>(std::llround(simTime().dbl()*1000.0));}
Bytes RSUApp::helloTranscript(const CavMsg& m)const{return PqcCrypto::canonical({PqcCrypto::text("CAV-PQC-v1"),PqcCrypto::text(m.getMessageType()),PqcCrypto::text(m.getSessionId()),PqcCrypto::text(m.getSenderId()),PqcCrypto::text(m.getKemPublicKeyHex()),PqcCrypto::text(m.getNonceHex()),PqcCrypto::text(std::to_string(m.getTimestampMs()))});}
Bytes RSUApp::replyTranscript(const CavMsg& m)const{return PqcCrypto::canonical({PqcCrypto::text("CAV-PQC-v1"),PqcCrypto::text(m.getMessageType()),PqcCrypto::text(m.getSessionId()),PqcCrypto::text(m.getSenderId()),PqcCrypto::text(m.getKemCiphertextHex()),PqcCrypto::text(m.getNonceHex()),PqcCrypto::text(std::to_string(m.getTimestampMs())),PqcCrypto::text(m.getTranscriptHashHex())});}
void RSUApp::handleHello(CavMsg* hello){if(std::string(hello->getReceiverId())!=par("rsuId").stringValue()||std::llabs(nowMs()-hello->getTimestampMs())>par("maxClockSkewMs").intValue()){fail("hello binding or freshness failed");return;}auto pk=PqcCrypto::unhex(hello->getSigningPublicKeyHex());auto sig=PqcCrypto::unhex(hello->getSignatureHex());if(!timed(this,cryptoTimeSignal_,[&]{return crypto_.verify(pk,crypto_.digest("CAV-PQC-v1/vehicle-hello",helloTranscript(*hello)),sig);})){fail("vehicle signature invalid");return;}Bytes ct,shared;if(!timed(this,cryptoTimeSignal_,[&]{return crypto_.kemEncaps(PqcCrypto::unhex(hello->getKemPublicKeyHex()),ct,shared);})){fail("encapsulation failed");return;}auto* reply=new CavMsg("serverHello");reply->setMessageType("RSU_SERVER_HELLO");reply->setSessionId(hello->getSessionId());reply->setSenderId(par("rsuId").stringValue());reply->setReceiverId(hello->getSenderId());reply->setKemCiphertextHex(PqcCrypto::hex(ct).c_str());reply->setSigningPublicKeyHex(PqcCrypto::hex(signing_.publicKey).c_str());auto nonce=crypto_.randomBytes(32);reply->setNonceHex(PqcCrypto::hex(nonce).c_str());reply->setTimestampMs(nowMs());auto t1hash=crypto_.digest("CAV-PQC-v1/vehicle-hello",helloTranscript(*hello));reply->setTranscriptHashHex(PqcCrypto::hex(t1hash).c_str());Bytes replySig;if(!timed(this,cryptoTimeSignal_,[&]{return crypto_.sign(signing_.secretKey,crypto_.digest("CAV-PQC-v1/rsu-server-hello",replyTranscript(*reply)),replySig);})){delete reply;fail("RSU signing failed");return;}reply->setSignatureHex(PqcCrypto::hex(replySig).c_str());auto context=crypto_.digest("CAV-PQC-v1/v2r-context",PqcCrypto::canonical({PqcCrypto::unhex(hello->getKemPublicKeyHex()),ct,PqcCrypto::unhex(hello->getNonceHex()),nonce,PqcCrypto::text(hello->getSenderId()),PqcCrypto::text(par("rsuId").stringValue())}));auto sk=timed(this,cryptoTimeSignal_,[&]{return crypto_.deriveKey(shared,context,"CAV-PQC-v1/session"+std::string(hello->getSessionId()));});auto transcript=crypto_.digest("CAV-PQC-v1/handshake",PqcCrypto::canonical({helloTranscript(*hello),replyTranscript(*reply)}));auto confirmation=timed(this,cryptoTimeSignal_,[&]{return crypto_.deriveKey(sk,transcript,"CAV-PQC-v1/finished");});pending_[hello->getSessionId()]={std::move(sk),std::move(confirmation),std::move(transcript),simTime()};reply->setByteLength(bytes(*reply));emit(overheadSignal_,reply->getByteLength());send(reply,"out");}
void RSUApp::handleFinished(CavMsg* finished){auto it=pending_.find(finished->getSessionId());if(it==pending_.end()||std::llabs(nowMs()-finished->getTimestampMs())>par("maxClockSkewMs").intValue()){fail("unknown or expired session");return;}if(PqcCrypto::hex(it->second.transcriptHash)!=std::string(finished->getTranscriptHashHex())){pending_.erase(it);fail("finished transcript mismatch");return;}auto expected=timed(this,cryptoTimeSignal_,[&]{return crypto_.hmacSha384(it->second.confirmationKey,PqcCrypto::canonical({PqcCrypto::text("CAV-PQC-v1/vehicle-finished"),it->second.transcriptHash,PqcCrypto::text(finished->getSessionId())}));});if(PqcCrypto::hex(expected)!=std::string(finished->getFinishedTagHex())){pending_.erase(it);fail("finished confirmation invalid");return;}emit(handshakeLatencySignal_,simTime()-it->second.started);emit(successSignal_,1L);recordScalar("v2r_session_key_match",true);EV_INFO<<"V2R authenticated key establishment succeeded; session key equality confirmed by Finished verification\n";pending_.erase(it);}
void RSUApp::handleMessage(cMessage* message){auto* packet=check_and_cast<CavMsg*>(message);try{if(std::string(packet->getMessageType())=="VEHICLE_HELLO")handleHello(packet);else if(std::string(packet->getMessageType())=="FINISHED")handleFinished(packet);else fail("unexpected RSU message");}catch(const std::exception& e){fail(e.what());}delete packet;}
void RSUApp::fail(const char* reason){EV_WARN<<"RSU V2R failure: "<<reason<<"\n";emit(failureSignal_,1L);}
